examples.template:
VStack(spacing: 16) {
    Image(systemName: "lock")
        .font(.system(size: 22))
        .foregroundStyle(theme.colors.textMuted)
        .frame(width: 56, height: 56)
        .background(RoundedRectangle(cornerRadius: 16).fill(theme.colors.bgMuted))
        .accessibilityHidden(true)
    VStack(spacing: 8) {
        Text("You don’t have access to {{appName|raw}}")
            .monarchTextStyle(.title)
            .foregroundStyle(theme.colors.textDefault)
        Text("Ask an admin of {{workspaceName|raw}} to give you access to {{appName|raw}}.")
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
    }
    .multilineTextAlignment(.center)
    MonarchFlowLayout(spacing: 8, rowSpacing: 8, justification: .center) {
        Button({{requestAccess}}) {}
            .buttonStyle(.monarch(.primary))
        Button({{back}}) {}
            .buttonStyle(.monarch(.secondary))
        Button({{switchWorkspace}}) {}
            .buttonStyle(.monarch(.ghost))
    }
    Button({{contact}}) {}
        .buttonStyle(.monarchLink(.inline))
}
.frame(maxWidth: .infinity)

